import pandas as pd

# Load predictions generated by XGBoost
df = pd.read_csv("model_output/test_predictions.csv")

# Calculate absolute prediction error
errors = (
    df["delay_min"] - df["predicted_delay_min"]
).abs()

# Calculate accuracy at different tolerances
tolerances = [5, 10, 15]

print("\nCOMMUTEIQ ETA PREDICTION PERFORMANCE")
print("------------------------------------")

for tolerance in tolerances:
    accuracy = (errors <= tolerance).mean() * 100

    print(
        f"Within +/- {tolerance} minutes: "
        f"{accuracy:.2f}%"
    )

print("\nTotal test predictions:", len(df))